sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   var pattern = /^\(\d{3}\)\s\d{3}-\d{4}$/; //(xxx) xxx-xxxx
	var phone = g_form.getValue('lea_phone_number');
	if(!pattern.test(phone)){

		phone = phone.replace(/\D/g,'');
		var regex = /^\d{10}$/;
		var is_valid = regex.test(phone);
		if(!is_valid){
			g_form.setValue('lea_phone_number', '');
			g_form.showFieldMsg("lea_phone_number", "Invalid phone number. Please enter 10 digits.", "error");

			setTimeout("var refocus = document.getElementById('sp_formfield_lea_phone_number');refocus.focus();",0);
		} else {
			phone = '(' + phone.slice(0,3) + ') ' + phone.slice(3,6)+'-' + phone.slice(6,10);
			g_form.setValue('lea_phone_number', phone);
		}
	}

}
